import {WEAPONS,RARITIES,AFFIXES,ENEMY_TYPES,SETS,GEMS,STORY} from './campaign.js';
import {SKILLS,RECIPES,iconHTML} from './hunt-expansion.js';
import {weaponFamily} from './engine.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const name=i=>i.kind==='weapon'?WEAPONS[i.weapon].name:i.name;
const rarity=i=>RARITIES[i.rarity];
let confirmSalvage=null,selectedItem=null,gearTab="all";
export function huntOverlay(game,root,{render,close,begin,help,toast}){
 const m=game.mode,p=game.p;
 const button=(label,attrs='',cls='secondary')=>`<button class="${cls}" ${attrs}>${label}</button>`;
 const resources=()=>`<div class="hunt-resources"><span>血之回响 <b>${game.gold}</b></span><span>血石碎片 <b>${game.materials}</b></span>${Object.entries(GEMS).map(([k,g])=>`<span>${g.name} <b>${game.gems[k]}</b></span>`).join('')}</div>`;
 const panel=(title,sub,body,small=false)=>`<section class="overlay" role="dialog" aria-modal="true" aria-label="${title}"><div class="panel hunt-panel ${small?'small':''}"><div class="panel-header"><div><p class="eyebrow">${sub}</p><h2>${title}</h2></div>${button('×','data-hclose aria-label="关闭"','icon-button')}</div>${body}</div></section>`;
 const itemCard=(i,actions='')=>{
  const r=rarity(i),w=i.kind==='weapon'?WEAPONS[i.weapon]:null;
  return `<article class="hunt-item ${game.isEquipped(i)?'equipped':''}" style="--item-color:${r.color}"><div class="item-cap"><span>${r.name} · ${w?'武器 Lv.'+i.level:i.slot==='coat'?'衣装':'符印'}</span><span>${game.isEquipped(i)?'已装备':''}</span></div>${iconHTML(i)}<h3>${esc(name(i))} <b>+${i.upgrade||0}</b></h3>${w?`<div class="item-stats"><b>${game.gearDamage(i.weapon,i)}</b> 基础伤害 <span>${w.range} 米 · ${w.type}</span></div><p>${w.desc}</p>`:`<div class="item-stats"><b>${i.slot==='coat'?(i.set==='church'?28:i.set==='beast'?16:20)+i.rarity*2+(i.upgrade||0)*5:(6+i.rarity+(i.upgrade||0)*2)+(i.slot==='coat'?'':'%')}</b> ${i.slot==='coat'?'最大生命':'武器伤害'}</div><p>${i.desc||'猎人衣装'}；品质也提高基础加成。</p><div class="set-line">${SETS[i.set].name}套装 · ${SETS[i.set].desc}</div>`}<div class="item-affix">${i.affix?AFFIXES[i.affix].name+'：'+AFFIXES[i.affix].desc:'无额外词缀'}</div>${w?`<div class="gem-line">◇ ${i.gem?GEMS[i.gem].name+'：'+GEMS[i.gem].desc:'宝石槽未镶嵌'}</div>`:''}<div class="item-actions">${actions}</div></article>`;
 };
 const gearButtons=i=>i.kind==='weapon'?p.slots.map((id,s)=>button(game.p.weapons[id]===i?'武器槽 '+(s+1)+' ✓':'装入槽 '+(s+1),`data-bagequip="${i.id}" data-slot="${s}" ${p.slots.some((other,j)=>j!==s&&other===i.weapon)?'disabled':''}`)).join(''):button(game.isEquipped(i)?'已穿戴':'穿戴',`data-bagequip="${i.id}"`);
 const saveButtons=()=>`<div class="save-controls">${button('导出进度','data-export')}${button('读取进度','data-import')}<input id="save-file" type="file" accept="application/json,.json" hidden><small>自动保存在此浏览器；导出文件可备份或迁移。读取后在梦境醒来。</small></div>`;
 let html='';
 if(m==='title')html=`<section class="overlay title-screen hunt-title" aria-label="游戏主菜单"><div class="title-content"><p class="eyebrow">A NAME LOST IN BLOOD</p><h1>烬途</h1><p class="english-title">长夜猎行</p><p class="title-desc">白花尽头是梦境。<br>钟声之下，亚南仍在狩猎。</p><div class="title-actions">${game.hasLocalSave?button('继续长夜 · 本机存档','data-continue','primary'):''}${button('签下血契 <span class="arrow">→</span>','id="start"','primary')}${button('操作指南','data-help')}</div><p class="title-note">猎人梦境 / 亚南中心<br>分区探索 · 枪反处决 · 双持与合成</p>${saveButtons()}</div><div class="game-tag"><small>I — II / THE LONG HUNT</small><p>长夜未尽</p></div><div class="title-footer"><span>横版动作冒险 · 血源风格扩展</span><span>键盘或横屏触控游玩</span></div></section>`;
 else if(m==='inventory'||m==='workshop'){
  const forge=m==='workshop',items=game.bag.filter(i=>gearTab==='all'||i.kind===gearTab);
  let chosen=items.find(i=>i.id===selectedItem)||items[0];selectedItem=chosen?.id;
  let detail='';if(chosen){const i=chosen,cost=game.upgradeCost(i),n=i.upgrade||0;
   let actions=gearButtons(i);
   if(forge)actions+=button(n>=6?'强化已满':`强化 +${n+1} · ${cost.gold} 回响 / ${cost.materials} 血石`,`data-upgrade="${i.id}" ${n>=6||game.gold<cost.gold||game.materials<cost.materials?'disabled':''}`,'primary')+(i.kind==='weapon'?`<div class="socket-actions">${Object.entries(GEMS).map(([key,g])=>button(g.name,`data-socket="${i.id}" data-gem="${key}" ${!game.gems[key]||i.gem===key?'disabled':''}`)).join('')}</div>`:'');
   if(!game.isEquipped(i))actions+=button(confirmSalvage===i.id?'确认分解 · '+(1+i.rarity+(i.upgrade||0))+' 血石':'分解装备',`data-salvage="${i.id}"`,'text-button');detail=itemCard(i,actions);
  }
  html=panel(forge?'猎人工坊':'猎人装备',forge?'WORKSHOP / BLOOD & IRON':'ARSENAL / ARMS • ARMOR • ARTS',resources()+`
  <div class="arsenal-layout"><aside class="loadout-rail"><p class="eyebrow">当前配装</p>${p.slots.map((id,slot)=>`<div class="equipped-tile" style="--item-color:${RARITIES[p.weapons[id].rarity].color}">${iconHTML({kind:'weapon',weapon:id})}<small>武器 ${slot+1}</small><strong>${WEAPONS[id].name}</strong><span>+${p.weapons[id].upgrade||0} · ${RARITIES[p.weapons[id].rarity].name}</span></div>`).join('')}${[p.coat,p.rune].map((i,j)=>`<div class="equipped-tile empty">${i?iconHTML(i):'<span class="empty-rune">◇</span>'}<strong>${i?esc(i.name):j?'符印空槽':'衣装空槽'}</strong></div>`).join('')}<div class="build-summary">生命 ${p.maxHp}<br>精力 100</div>${button(p.dualWield?'双持已开启 · B':'开启双持 · B','data-dual')}<small class="hunt-note">两个近战槽可双持：副手追击 +45%，每段多消耗 7 精力。</small></aside>
  <div class="bag-pane"><nav class="arsenal-tabs">${[['all','全部'],['weapon','武器'],['attire','衣装 / 符印']].map(([id,label])=>button(label,`data-tab="${id}" aria-pressed="${gearTab===id}"`,gearTab===id?'primary':'secondary')).join('')}</nav><div class="bag-grid" aria-label="背包装备">${items.map(i=>`<button class="bag-cell ${i.id===selectedItem?'active':''}" style="--item-color:${rarity(i).color}" data-item="${i.id}" aria-label="${esc(name(i))} ${rarity(i).name} +${i.upgrade||0}">${iconHTML(i)}<span>+${i.upgrade||0}</span>${game.isEquipped(i)?'<b>装</b>':''}</button>`).join('')}${Array.from({length:Math.max(0,24-items.length)},()=>'<span class="bag-cell vacant"></span>').join('')}</div><div class="rarity-key">${RARITIES.map(r=>`<span style="color:${r.color}">◆ ${r.name}</span>`).join('')}</div><p class="hunt-note">${items.length} 件装备 · 选择图标查看属性、强化与宝石。换下的装备会保留。</p><div class="active-sets">${Object.entries(SETS).map(([id,set])=>`<span class="${game.setActive(id)?'on':''}">${set.name} ${game.setActive(id)?'2/2 · '+set.desc:'未激活'}</span>`).join('')}</div></div><div class="gear-detail">${detail||'<p>此分类没有装备。</p>'}</div></div>
  ${forge?`<div class="section-rule"><span>图纸合成</span><small>探索解锁 · 每张图纸制作一件专属武器</small></div><div class="recipe-grid">${RECIPES.map(r=>{const known=game.flags[r.flag],made=game.flags['crafted-'+r.id];return `<article class="recipe-card" style="--item-color:${RARITIES[r.rarity].color}">${iconHTML({kind:'weapon',weapon:r.weapon})}<div><h3>${WEAPONS[r.weapon].name}</h3><p>${RARITIES[r.rarity].name} · ${r.gold} 回响 / ${r.materials} 血石</p><small>${known?'图纸已解锁':r.flag==='badge'?'线索：暗渠猎人徽章':r.flag==='eileen'?'线索：阁楼乌鸦猎人':'线索：斩断干船坞悬挂遗物'}</small>${button(made?'已合成':known?'合成武器':'未找到图纸',`data-craft="${r.id}" ${made||!known||game.gold<r.gold||game.materials<r.materials?'disabled':''}`)}</div></article>`;}).join('')}</div><p class="hunt-note">强化必定成功，最高 +6。武器每级伤害 +10%；衣装生命 +5；符印伤害 +2%。换宝石退还旧宝石。</p>`:
  `<div class="section-rule"><span>猎人秘术</span><small>K / Q · 两个技能槽 · 每次消耗 25 精力</small></div><div class="skill-grid">${Object.entries(SKILLS).map(([id,skill])=>{const locked=skill.flag&&!game.flags[skill.flag];return `<article class="skill-tile" style="--skill-color:${skill.color}"><div class="skill-art skill-${id}"></div><div><h3>${skill.name}</h3><p>${skill.desc}</p><small>${skill.damage} 伤害 · ${skill.radius} 米 · ${skill.cooldown} 秒冷却</small><div>${[0,1].map(slot=>button(game.skillSlots[slot]===id?(slot?'Q':'K')+' 已装备':'装备到 '+(slot?'Q':'K'),`data-skill="${id}" data-skill-slot="${slot}" ${locked||game.skillSlots[1-slot]===id?'disabled':''}`)).join('')}</div>${locked?'<small>探索解锁：'+(skill.flag==='eileen'?'阁楼乌鸦猎人':'暗渠猎人徽章')+'</small>':''}</div></article>`;}).join('')}</div>`}
  `+saveButtons());
 }else if(m==='loot'){
  const item=game.loot.find(i=>i.id===game.pendingLoot);if(!item||!['weapon','attire'].includes(item.kind))return false;
  html=panel('发现装备','HUNT TROPHY',`<div class="hunt-loot-layout">${itemCard(item)}<div class="loot-decisions"><p>可先收入背包，或直接换装。</p>${item.kind==='weapon'?p.slots.map((id,s)=>{const old=p.weapons[id],diff=game.gearDamage(item.weapon,item)-game.gearDamage(id,old);return button(`<small>替换武器槽 ${s+1} · ${WEAPONS[id].name}</small><strong>${game.gearDamage(id,old)} → ${game.gearDamage(item.weapon,item)} <em>${diff>=0?'+':''}${diff}</em></strong>`,`data-hswap="${s}" ${p.slots.some((other,j)=>j!==s&&other===item.weapon)?'disabled':''}`,'swap-option');}).join(''):button('立即穿戴','data-hswap="0"','primary')}${button('收入背包','data-collect','primary')}${button('暂时留在原地','data-hclose')}<p class="hunt-note">旧装备会保留在背包；升级、宝石与套装效果也会保留。</p></div></div>`);
 }else if(m==='dialogue'){
  const story=game.dialogueStory();if(!story)return false;
  html=panel(story.title,story.speaker,`<div class="story-copy">${story.text.map(t=>`<p>${t}</p>`).join('')}</div>${game.dialogue==='doll'?resources()+`<p>回响成长 ${game.growth}/10 · 每级最大生命 +10</p>${button('以 '+(100+game.growth*60)+' 回响提升生命',`data-grow ${game.gold<100+game.growth*60||game.growth>=10?'disabled':''}`)}`:''}<div class="story-actions">${story.choices?story.choices.map(c=>button(c.label,`data-choice="${c.id}"`,'primary')).join(''):button(game.dialogue==='doll'&&game.flags.gift?'继续狩猎':story.button,'data-story','primary')}</div>`);
 }else if(m==='travel'){
  html=panel('在何处醒来','AWAKENING / DISCOVERED LANTERNS',`<div class="travel-grid">${Object.values(game.visitedLamps).map(l=>`<button class="travel-card city-card" data-travel="${l.area}" data-x="${l.x}"><span>CHAPTER II · 已点亮</span><h3>${({yharnam:'猎民街区',bridge:'大桥前灯',tomb:'墓园前灯'})[l.area]||l.area}</h3><p>${game.flags.complete?'主线已完成 · 继续回访与探索':'从已点亮的灯火出发'}</p></button>`).join('')}<button class="travel-card old-card" data-travel="sanctum"><span>LEGACY TRIAL</span><h3>失落圣所</h3><p>保留的旧日试炼</p></button></div><p class="hunt-note">墓园铁门从另一侧开启后，可从街区直接折返。重访区域时普通敌人复苏；Boss、宝箱、剧情选择会保留。</p>`);
 }else if(m==='lamp')html=panel('灯火仍在','LANTERN',`<p>此处成为本章重返位置。休整会补充生命、3 个血瓶和 12 发水银弹，并让普通敌人复苏。</p>${button('在灯边休整','data-rest','primary')}${button('返回猎人梦境','data-home')}${button('继续前行','data-hclose')}`,true);
 else if(m==='paused')html=panel('在长夜中稍作停留','PAUSED',`<p>当前章节：${game.level.name||'失落圣所'}</p>${button('继续探索','data-hclose','primary')}${button('猎人手记 / 地图','data-journal')}${button('操作指南','data-help')}${button('返回梦境','data-home')}${saveButtons()}`,true);
 else if(m==='dead'||m==='won')html=panel(m==='dead'?'你倒在了长夜里':'旧日试炼完成',m==='dead'?'THE HUNTER WILL RETURN':'TRIAL COMPLETE',`<p>${m==='dead'?'装备与强化保留。回响留在倒下的位置，下一次倒下会替换旧的遗落回响。':'余烬守卫已经倒下。带着装备回到梦境，长夜的狩猎仍在继续。'}</p><div class="build-summary"><span>击败 ${game.kills}</span><span>遗落回响 ${game.lostEchoes?.amount||0}</span></div>${button(m==='dead'?'从灯火处重返':'返回梦境',m==='dead'?'data-respawn':'data-home','primary')}${m==='dead'?button('在梦境醒来','data-home'):''}${saveButtons()}`,true);
 else if(m==='journal'){
  const done=Object.keys(game.flags).filter(k=>k.startsWith('boss-')&&game.flags[k]).length;
  html=panel('猎人手记','CHRONICLE / EVERY WINDOW HAS A STORY',`<div class="exploration-map"><div class="map-hub">猎人梦境<small>人偶 · 工坊 · 记忆墓碑</small></div><div class="map-areas">${[['yharnam','01 · 猎民街区','高窗 / 屋顶 / 回访'],['aqueduct','02 · 干船坞与暗渠','阁楼 / 陷坑 / 图纸'],['tomb','03 · 欧顿墓园','铁门捷径 / 神父 / 胸针'],['bridge','支线 · 大桥','猎犬群 / 巨兽 / 头部失衡']].map(([id,title,desc])=>`<div class="${game.chapter===id?'here':''}"><b>${title}</b><small>${game.flags['visited-'+id]?desc:'未探索'}</small>${game.chapter===id?'<em>所在区域</em>':''}</div>`).join('')}</div><p>主路：街区 → 暗渠 → 墓园。街区高层通往大桥；墓园铁门开启后直接返回街区。<br>W / S 攀梯，空格离梯。攀墙印记让街区高墙成为新路线。</p></div><div class="journal-status"><span>${done}/2 亚南猎物</span><span>${game.flags.wallClimb?'✓':'○'} 攀墙印记</span><span>${game.flags.badge?'✓':'○'} 猎人徽章</span><span>${game.flags.shortcut?'✓':'○'} 铁门捷径</span></div><div class="quest-grid">${game.questNotes().map(q=>`<article><small>${q.state}</small><h3>${q.title}</h3><p>${q.text}</p></article>`).join('')}</div><div class="section-rule"><span>已经发生的事</span><small>你的选择会随存档保留</small></div><ol class="chronicle">${game.journal.length?game.journal.map(n=>`<li><time>${Math.floor(n.at/60)}:${String(n.at%60).padStart(2,'0')}</time>${esc(n.text)}</li>`).join(''):'<li>这一夜尚未留下记录。</li>'}</ol><div class="boss-notes"><p><b>神父：</b>三个阶段都能枪反。预警最后 0.28 秒变为金色 F；命中后 2.4 秒内贴近按 J。</p><p><b>圣职者野兽：</b>不能普通枪反。收招时 F 射击头部，3 次命中使其失衡，3.2 秒内近身处决。</p><p><b>精英：</b>不会被普通轻击连续打断。留精力翻滚、利用枪反与第三段重击。</p></div>`);
 }else return false;
 root.innerHTML=html;
 root.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>{selectedItem=b.dataset.item;render();});
 root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{gearTab=b.dataset.tab;render();});
 root.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{game.acceptDialogue(b.dataset.choice);render();});
 root.querySelectorAll('[data-craft]').forEach(b=>b.onclick=()=>{if(game.craft(b.dataset.craft))toast('图纸合成完成 · 装备已收入背包');render();});
 root.querySelectorAll('[data-skill]').forEach(b=>b.onclick=()=>{game.selectSkill(+b.dataset.skillSlot,b.dataset.skill);render();});
 root.querySelector('[data-dual]')?.addEventListener('click',()=>{game.toggleDual();render();});
 root.querySelectorAll('[data-hclose]').forEach(b=>b.onclick=close);
 root.querySelector('#start')?.addEventListener('click',begin);
 root.querySelector('[data-continue]')?.addEventListener('click',()=>{try{game.importSave(JSON.parse(localStorage.getItem('emberfall-hunt-v4')));render();toast('长夜仍在 · 已恢复本机进度');}catch{toast('本机进度无法读取，请使用导出的备份');}});
 root.querySelectorAll('[data-help]').forEach(b=>b.onclick=help);
 root.querySelectorAll('[data-journal]').forEach(b=>b.onclick=()=>{game.mode='journal';render();});
 root.querySelectorAll('[data-bagequip]').forEach(b=>b.onclick=()=>{game.equipBag(b.dataset.bagequip,+b.dataset.slot);render();});
 root.querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>{if(game.upgrade(b.dataset.upgrade))toast('强化成功');render();});
 root.querySelectorAll('[data-socket]').forEach(b=>b.onclick=()=>{if(game.socket(b.dataset.socket,b.dataset.gem))toast('宝石已镶嵌');render();});
 root.querySelectorAll('[data-salvage]').forEach(b=>b.onclick=()=>{if(confirmSalvage===b.dataset.salvage){game.salvage(confirmSalvage);confirmSalvage=null;}else confirmSalvage=b.dataset.salvage;render();});
 root.querySelectorAll('[data-travel]').forEach(b=>b.onclick=()=>{game.travel(b.dataset.travel,b.dataset.x?+b.dataset.x:undefined);render();});
 root.querySelectorAll('[data-home]').forEach(b=>b.onclick=()=>{game.travel('dream');render();});
 root.querySelector('[data-respawn]')?.addEventListener('click',()=>{game.respawn();render();});
 root.querySelector('[data-rest]')?.addEventListener('click',()=>{game.respawn();render();});
 root.querySelector('[data-story]')?.addEventListener('click',()=>{game.acceptDialogue();render();});
 root.querySelector('[data-grow]')?.addEventListener('click',()=>{game.grow();render();});
 root.querySelector('[data-collect]')?.addEventListener('click',()=>{game.collectLoot();render();});
 root.querySelectorAll('[data-hswap]').forEach(b=>b.onclick=()=>{game.chooseLoot(+b.dataset.hswap);render();});
 root.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(game.exportSave(),null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='emberfall-hunt-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('进度已导出为存档文件');});
 root.querySelector('[data-import]')?.addEventListener('click',()=>root.querySelector('#save-file').click());
 root.querySelector('#save-file')?.addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2e6)throw Error('存档文件过大');game.importSave(JSON.parse(await file.text()));render();toast('进度已读取 · 在梦境醒来');}catch(err){toast(err.message||'无法读取此存档',6);}});
 root.querySelector('button:not(:disabled)')?.focus({preventScroll:true});return true;
}
